class SumCalculator:
    def __init__(self, areaCalculator: AreaCalculator) -> None:
        self.calculator = areaCalculator

    def calculate(self):
        return self.calculator.sum()

class JSONOutputter:
    def __init__(self, calculator: SumCalculator) -> None:
        self.calculator = calculator

    def output(self):
        data = {
            'sum': self.calculator.calculate()
        }
        return json.dumps(data)

class HTMLOutputter:
    def __init__(self, calculator: SumCalculator) -> None:
        self.calculator = calculator

    def output(self):
        return f"Sum of the areas of provided shapes: {self.calculator.calculate()}"
